import esbuild from "esbuild";
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const rootDir = path.resolve(__dirname, "..");

async function buildExport() {
  console.log("🔨 Building Standalone EDUcraft HTML Export Bundle (Rust-native)...");

  // Primary output: src-tauri/assets/ for Rust include_str!() compile-time embedding
  const rustAssetsDir = path.join(rootDir, "src-tauri", "assets");
  const rustJsOut = path.join(rustAssetsDir, "ui_bundle.js");
  const rustCssOut = path.join(rustAssetsDir, "ui_bundle.css");

  // Secondary output: keep export_bundle_data.js as web-browser fallback
  const stubExportDataPath = path.join(rootDir, "src", "data", "export_bundle_data.js");
  const tempDir = path.join(rootDir, ".export_temp");

  if (!fs.existsSync(tempDir)) fs.mkdirSync(tempDir, { recursive: true });
  if (!fs.existsSync(rustAssetsDir)) fs.mkdirSync(rustAssetsDir, { recursive: true });

  // esbuild plugin: stub export_bundle_data to avoid circular embedding
  const stubExportDataPlugin = {
    name: "stub-export-bundle-data",
    setup(build) {
      build.onResolve({ filter: /export_bundle_data(\.js)?$/ }, (args) => ({
        path: args.path,
        namespace: "stub-export-data",
      }));
      build.onLoad({ filter: /.*/, namespace: "stub-export-data" }, () => ({
        contents: `
          export const EDUCRAFT_EXPORT_BUNDLE_JS = "";
          export const EDUCRAFT_EXPORT_TAILWIND_CSS = "";
        `,
        loader: "js",
      }));
    },
  };

  // 1. Bundle standalone React application
  await esbuild.build({
    entryPoints: [path.join(rootDir, "src", "standalone.jsx")],
    bundle: true,
    minify: true,
    target: ["es2022", "chrome100", "firefox100", "safari15"],
    format: "iife",
    jsx: "automatic",
    outfile: path.join(tempDir, "bundle.js"),
    external: ["tailwindcss"],
    plugins: [stubExportDataPlugin],
    define: { "process.env.NODE_ENV": '"production"' },
    loader: {
      ".js": "jsx",
      ".jsx": "jsx",
      ".css": "text",
      ".png": "dataurl",
      ".svg": "text",
      ".json": "json"
    }
  });

  const jsCode = fs.readFileSync(path.join(tempDir, "bundle.js"), "utf8");

  // 2. Extract compiled CSS from dist/assets or fallback to src/styles.css
  let cssCode = "";
  const distAssetsDir = path.join(rootDir, "dist", "assets");
  if (fs.existsSync(distAssetsDir)) {
    const cssFiles = fs.readdirSync(distAssetsDir).filter((f) => f.endsWith(".css"));
    if (cssFiles.length > 0) {
      cssCode = fs.readFileSync(path.join(distAssetsDir, cssFiles[0]), "utf8");
    }
  }
  if (!cssCode) {
    const mainCssPath = path.join(rootDir, "src", "styles.css");
    if (fs.existsSync(mainCssPath)) cssCode = fs.readFileSync(mainCssPath, "utf8");
  }

  // 3. Write raw assets for Rust include_str!() — plain text, no JSON.stringify wrapper
  fs.writeFileSync(rustJsOut, jsCode, "utf8");
  fs.writeFileSync(rustCssOut, cssCode, "utf8");
  console.log(`✅ Rust assets written:`);
  console.log(`   JS  → src-tauri/assets/ui_bundle.js  (${(jsCode.length / 1024).toFixed(1)} KB)`);
  console.log(`   CSS → src-tauri/assets/ui_bundle.css (${(cssCode.length / 1024).toFixed(1)} KB)`);

  // 4. Update JS stub for web-browser fallback (non-Tauri mode)
  const stubContent = `// Auto-generated by scripts/build-export-bundle.js — DO NOT EDIT MANUALLY
// Web-browser fallback: used when running EDUcraft in a plain browser (no Tauri).
// In Tauri desktop builds, export is handled by Rust — see src-tauri/src/commands/export_book.rs
export const EDUCRAFT_EXPORT_BUNDLE_JS = ${JSON.stringify(jsCode)};
export const EDUCRAFT_EXPORT_TAILWIND_CSS = ${JSON.stringify(cssCode)};
`;
  fs.writeFileSync(stubExportDataPath, stubContent, "utf8");
  console.log(`   Web fallback → src/data/export_bundle_data.js`);

  // 5. Clean temp
  fs.rmSync(tempDir, { recursive: true, force: true });
  console.log("🎉 Done! Run 'cargo build' inside src-tauri/ to embed UI assets in the Rust binary.");
}

buildExport().catch((err) => {
  console.error("❌ Error building export bundle:", err);
  process.exit(1);
});
